-- =====================================================================
-- Session 503 migration — the STRAGGLERS: the last orphan cross-reference cards outside the gospels, rewritten Come-and-See and threaded.
-- Books: Joshua, Revelation, Romans, 1 Thessalonians, Genesis, Ezekiel, 2 Esdras, 2 Baruch. 27 cards rewritten in place (ids and verse pairs kept), 0 new threads, 0 anchors, 27 thread members added.
-- Drafted and read on Claude Fable 5.1; every note composed by script (build503.py): target verse whole (canon from parsed/canon.json, the
-- restored-names KJV; extras from the live text), source verse whole as it reads live, then the prose. Edition-aware: sources in 2 Esdras and
-- 2 Baruch, targets in the Testaments of the Twelve Patriarchs and the Ascension of Isaiah resolve through e.slug.
-- Safety (DO block, before any write): RAISES if a card is gone or sits on another verse pair, if a source verse's live text differs from the
-- read-back, if a card's live note is neither the note this was written against nor the new one, if a card is already in a thread this file does
-- not put it in, or if a thread to join is missing or its id moved.  Idempotent: a re-run reports 0 rewritten / 0 inserted.  Nothing is deleted.
-- Run: python3 api/apply_migration.py data-schema/migrations/session503_stragglers_rebuild.sql
-- =====================================================================
\echo 'session503 — stragglers rebuild starting...'
BEGIN;
CREATE TEMP TABLE _s503_c (id BIGINT, s_ed TEXT, s_book TEXT, src_ch INT, src_v INT, src_text TEXT, t_ed TEXT, tgt_slug TEXT, tgt_ch INT, tgt_v INT, old_note TEXT, new_note TEXT) ON COMMIT DROP;
INSERT INTO _s503_c VALUES
(161403,'canon','joshua',12,2,$n$Sihon king of the Amorites, who dwelt in Heshbon, and ruled from Aroer, which is upon the bank of the river Arnon, and from the middle of the river, and from half Gilead, even unto the river Jabbok, which is the border of the children of Ammon;$n$,'canon','psalms',136,19,$n$*Sihon king of the Amorites: for his mercy endureth for ever* (Psalms 136:19). The first name in Joshua's east-of-Jordan list — *Sihon king of the Amorites, who dwelt in Heshbon* (Joshua 12:2) — is sung by name in the psalm as a deed of Yahuah's mercy that endureth for ever; the memorial and the praise name the same king.$n$,$n$Psalm 136:19 — *Sihon king of the Amorites: for his mercy endureth for ever:* *Sihon king of the Amorites, who dwelt in Heshbon, and ruled from Aroer, which is upon the bank of the river Arnon, and from the middle of the river, and from half Gilead, even unto the river Jabbok, which is the border of the children of Ammon;* (Joshua 12:2) Joshua's roll opens east of Jordan with Sihon, his city, his rivers, the whole stretch he ruled. The psalm needs none of that. It sings his name in one line and gives the whole deed to Yahuah (the LORD), *for his mercy endureth for ever*. The same king stands in both: a border in the memorial, a mercy in the song.$n$),
(161404,'canon','joshua',12,2,$n$Sihon king of the Amorites, who dwelt in Heshbon, and ruled from Aroer, which is upon the bank of the river Arnon, and from the middle of the river, and from half Gilead, even unto the river Jabbok, which is the border of the children of Ammon;$n$,'canon','psalms',135,11,$n$*Sihon king of the Amorites, and Og king of Bashan, and all the kingdoms of Canaan* (Psalms 135:11). Joshua's *Sihon king of the Amorites* (Joshua 12:2) heads the same pair the praise of Yashar'el rehearses — Sihon and Og, the two great kings overthrown, the firstfruits of the land Yahuah gave.$n$,$n$Psalm 135:11 — *Sihon king of the Amorites, and Og king of Bashan, and all the kingdoms of Canaan:* *Sihon king of the Amorites, who dwelt in Heshbon, and ruled from Aroer, which is upon the bank of the river Arnon, and from the middle of the river, and from half Gilead, even unto the river Jabbok, which is the border of the children of Ammon;* (Joshua 12:2) Joshua gives Sihon his own verse and his own borders. The psalm puts him in one breath with Og and *all the kingdoms of Canaan*, the two kings east of Jordan at the head of the whole land. What the memorial spreads over a chapter, the praise of Yashar'el (Israel) gathers into a single line, and the one who smote them is Yahuah (the LORD).$n$),
(161407,'canon','joshua',12,4,$n$And the coast of Og king of Bashan, which was of the remnant of the giants, that dwelt at Ashtaroth and at Edrei,$n$,'canon','psalms',136,20,$n$*And Og the king of Bashan: for his mercy endureth for ever* (Psalms 136:20). The second east-of-Jordan name — *Og king of Bashan, which was of the remnant of the giants* (Joshua 12:4) — is sung by name in the psalm as a deed of Yahuah's mercy that endureth for ever; the memorial and the praise name the same giant-king overthrown.$n$,$n$Psalm 136:20 — *And Og the king of Bashan: for his mercy endureth for ever:* *And the coast of Og king of Bashan, which was of the remnant of the giants, that dwelt at Ashtaroth and at Edrei,* (Joshua 12:4) Joshua remembers Og as a king out of *the remnant of the giants*, holding Ashtaroth and Edrei. The psalm does not dwell on what he was. It names him and hands the victory to Yahuah (the LORD), *for his mercy endureth for ever*. The giant king is one more line in a song about mercy, and that is the whole of his memorial there.$n$),
(161408,'canon','joshua',12,6,$n$Them did Moses the servant of Yahuah (LORD) and the children of Yashar'el (Israel) smite: and Moses the servant of Yahuah (LORD) gave it for a possession unto the Reubenites, and the Gadites, and the half tribe of Manasseh.$n$,'canon','deuteronomy',3,18,$n$*And I commanded you at that time, saying, Yahuah Elohaychem (The LORD your God) hath given you this land to possess it: ye shall pass over armed before your brethren the children of Yashar'el (Israel), all that are meet for the war* (Deuteronomy 3:18). Joshua's memorial records that *Moses the servant of Yahuah (LORD) gave it for a possession unto the Reubenites, and the Gadites, and the half tribe of Manasseh* (Joshua 12:6) — the very allotment Moses commanded; the land east of Jordan given as Yahuah's gift to possess.$n$,$n$Deuteronomy 3:18 — *And I commanded you at that time, saying, Yahuah Elohaychem (The LORD your God) hath given you this land to possess it: ye shall pass over armed before your brethren the children of Yashar'el (Israel), all that are meet for the war.* *Them did Moses the servant of Yahuah (LORD) and the children of Yashar'el (Israel) smite: and Moses the servant of Yahuah (LORD) gave it for a possession unto the Reubenites, and the Gadites, and the half tribe of Manasseh.* (Joshua 12:6) Joshua writes that Moses gave the east country to Reuben, Gad and half Manasseh. Deuteronomy keeps Moses' own words at the giving: the land was the gift of Yahuah (the LORD) to possess, and the men who received it were to cross over armed ahead of their brethren until the rest of the house had theirs. The possession came with a duty to the whole of Yashar'el (Israel).$n$),
(161409,'canon','joshua',12,6,$n$Them did Moses the servant of Yahuah (LORD) and the children of Yashar'el (Israel) smite: and Moses the servant of Yahuah (LORD) gave it for a possession unto the Reubenites, and the Gadites, and the half tribe of Manasseh.$n$,'canon','psalms',136,21,$n$*And gave their land for an heritage: for his mercy endureth for ever* (Psalms 136:21). *Moses the servant of Yahuah (LORD)... gave it for a possession* (Joshua 12:6) — the psalm names the same gift as Yahuah's own giving; the land becomes an heritage by his mercy that endureth for ever, not by conquest alone.$n$,$n$Psalm 136:21 — *And gave their land for an heritage: for his mercy endureth for ever:* *Them did Moses the servant of Yahuah (LORD) and the children of Yashar'el (Israel) smite: and Moses the servant of Yahuah (LORD) gave it for a possession unto the Reubenites, and the Gadites, and the half tribe of Manasseh.* (Joshua 12:6) Moses gave the east country *for a possession*, Joshua says. The psalm says who gave it and what it is: Yahuah (the LORD) *gave their land for an heritage*, and gave it for his mercy's sake. A possession is what men hold by the sword; an heritage is what a father leaves his children. The psalm calls the land the second thing.$n$),
(161410,'canon','joshua',12,6,$n$Them did Moses the servant of Yahuah (LORD) and the children of Yashar'el (Israel) smite: and Moses the servant of Yahuah (LORD) gave it for a possession unto the Reubenites, and the Gadites, and the half tribe of Manasseh.$n$,'canon','psalms',136,22,$n$*Even an heritage unto Yashar'el (Israel) his servant: for his mercy endureth for ever* (Psalms 136:22). The possession *Moses the servant of Yahuah (LORD) gave... unto the Reubenites, and the Gadites, and the half tribe of Manasseh* (Joshua 12:6) is the heritage the psalm gives *unto Yashar'el (Israel) his servant* — the inheritance of his people, secured by his enduring mercy.$n$,$n$Psalm 136:22 — *Even an heritage unto Yashar'el (Israel) his servant: for his mercy endureth for ever.* *Them did Moses the servant of Yahuah (LORD) and the children of Yashar'el (Israel) smite: and Moses the servant of Yahuah (LORD) gave it for a possession unto the Reubenites, and the Gadites, and the half tribe of Manasseh.* (Joshua 12:6) The three tribes east of Jordan took their portion from Moses' hand. The psalm names whose heritage it is in the end: *Yashar'el (Israel) his servant*, the whole house, not three tribes and not the men who fought for it. Yahuah (the LORD) gave it to the servant he chose, for his mercy's sake, and the song keeps the giving for ever.$n$),
(161411,'canon','joshua',12,7,$n$And these are the kings of the country which Joshua and the children of Yashar'el (Israel) smote on this side Jordan on the west, from Baal-gad in the valley of Lebanon even unto the mount Halak, that goes up to Seir; which Joshua gave unto the tribes of Yashar'el (Israel) for a possession according to their divisions;$n$,'canon','nehemiah',9,23,$n$*Their children also multipliedst thou as the stars of heaven, and broughtest them into the land, concerning which thou hadst promised to their fathers, that they should go in to possess it* (Nehemiah 9:23). Joshua's record that *Joshua gave unto the tribes of Yashar'el (Israel) for a possession according to their divisions* (Joshua 12:7) is the keeping of the promise to the fathers; the conquest catalogue is the seed-promise to Abraham, Isaac, and Jacob performed.$n$,$n$Nehemiah 9:23 — *Their children also multipliedst thou as the stars of heaven, and broughtest them into the land, concerning which thou hadst promised to their fathers, that they should go in to possess it.* *And these are the kings of the country which Joshua and the children of Yashar'el (Israel) smote on this side Jordan on the west, from Baal-gad in the valley of Lebanon even unto the mount Halak, that goes up to Seir; which Joshua gave unto the tribes of Yashar'el (Israel) for a possession according to their divisions;* (Joshua 12:7) Joshua divides the west country among the tribes. The Levites, confessing generations later, say why there were tribes to divide it among: Yahuah (the LORD) multiplied the children as the stars and brought them into the land he had promised their fathers. Abraham's stars and Abraham's land meet in Joshua's chapter. The dividing is a promise being kept, not a conquest being counted.$n$),
(161412,'canon','joshua',12,7,$n$And these are the kings of the country which Joshua and the children of Yashar'el (Israel) smote on this side Jordan on the west, from Baal-gad in the valley of Lebanon even unto the mount Halak, that goes up to Seir; which Joshua gave unto the tribes of Yashar'el (Israel) for a possession according to their divisions;$n$,'canon','nehemiah',9,24,$n$*So the children went in and possessed the land, and thou subduedst before them the inhabitants of the land, the Canaanites, and gavest them into their hands, with their kings* (Nehemiah 9:24). *Joshua gave unto the tribes of Yashar'el (Israel) for a possession according to their divisions* (Joshua 12:7) — the confession names Yahuah as the one who subdued the kings and gave the land; the dividing among the tribes is his faithful gift, not Israel's wage.$n$,$n$Nehemiah 9:24 — *So the children went in and possessed the land, and thou subduedst before them the inhabitants of the land, the Canaanites, and gavest them into their hands, with their kings, and the people of the land, that they might do with them as they would.* *And these are the kings of the country which Joshua and the children of Yashar'el (Israel) smote on this side Jordan on the west, from Baal-gad in the valley of Lebanon even unto the mount Halak, that goes up to Seir; which Joshua gave unto the tribes of Yashar'el (Israel) for a possession according to their divisions;* (Joshua 12:7) Joshua's chapter says Joshua and the children of Yashar'el (Israel) smote the kings and Joshua gave the land. The Levites tell the same story to Yahuah (the LORD) himself with a different subject: *thou subduedst before them the inhabitants of the land*, and *gavest them into their hands, with their kings*. The man's name is on the chapter; the deed is the Father's.$n$),
(161413,'canon','joshua',12,7,$n$And these are the kings of the country which Joshua and the children of Yashar'el (Israel) smote on this side Jordan on the west, from Baal-gad in the valley of Lebanon even unto the mount Halak, that goes up to Seir; which Joshua gave unto the tribes of Yashar'el (Israel) for a possession according to their divisions;$n$,'canon','psalms',135,12,$n$*And gave their land for an heritage, an heritage unto Yashar'el (Israel) his people* (Psalms 135:12). The land *Joshua gave unto the tribes of Yashar'el (Israel) for a possession* (Joshua 12:7) is the heritage the praise of Yashar'el lays to Yahuah's account — given to his people, the promise to the fathers brought to its possession.$n$,$n$Psalm 135:12 — *And gave their land for an heritage, an heritage unto Yashar'el (Israel) his people.* *And these are the kings of the country which Joshua and the children of Yashar'el (Israel) smote on this side Jordan on the west, from Baal-gad in the valley of Lebanon even unto the mount Halak, that goes up to Seir; which Joshua gave unto the tribes of Yashar'el (Israel) for a possession according to their divisions;* (Joshua 12:7) Joshua gave the tribes their possession *according to their divisions*. The psalm has no surveyor's line in it, only the gift and the people: *an heritage unto Yashar'el (Israel) his people*. Joshua measured the land out; Yahuah (the LORD) gave it, and the psalm goes straight on to the giver: *Thy name, O Yahuah (LORD), endureth for ever* (Psalm 135:13). The memorial of the kings is his.$n$),
(161398,'canon','joshua',12,24,$n$The king of Tirzah, one: all the kings thirty and one.$n$,'canon','psalms',136,17,$n$*To him which smote great kings: for his mercy endureth for ever* (Psalms 136:17). The closing tally — *all the kings thirty and one* (Joshua 12:24) — is the sum of the very deeds the psalm names as Yahuah's; every king in the list is a line in the memorial of his mercy that endureth for ever.$n$,$n$Psalm 136:17 — *To him which smote great kings: for his mercy endureth for ever:* *The king of Tirzah, one: all the kings thirty and one.* (Joshua 12:24) *All the kings thirty and one* is the sum of a chapter that gives every king one line and the word *one*. The psalm adds the same column differently: *To him which smote great kings*, and the reason under it, *for his mercy endureth for ever*. Thirty-one lines of a memorial become one line of praise, and the one who smote them is named.$n$),
(161399,'canon','joshua',12,24,$n$The king of Tirzah, one: all the kings thirty and one.$n$,'canon','psalms',135,10,$n$*Who smote great nations, and slew mighty kings* (Psalms 135:10). *All the kings thirty and one* (Joshua 12:24) are the great nations and mighty kings the praise of Yashar'el lays at Yahuah's feet; the catalogue Joshua keeps is the same recital the psalm sings.$n$,$n$Psalm 135:10 — *Who smote great nations, and slew mighty kings;* *The king of Tirzah, one: all the kings thirty and one.* (Joshua 12:24) Joshua's tally stops at thirty and one. The psalm never counts; it says *great nations* and *mighty kings* and leaves the number to the book that kept it. The two belong together because they are one deed told twice, once as a record for the land and once as a song for the house, and in the song it is Yahuah (the LORD) who smote them.$n$),
(161400,'canon','joshua',12,24,$n$The king of Tirzah, one: all the kings thirty and one.$n$,'canon','nehemiah',9,24,$n$*So the children went in and possessed the land, and thou subduedst before them the inhabitants of the land, the Canaanites, and gavest them into their hands, with their kings, and the people of the land, that they might do with them as they would* (Nehemiah 9:24). The Levites' confession rehearses Joshua's tally — *all the kings thirty and one* (Joshua 12:24) — as Yahuah's subduing; he gave the kings into their hands, the catalogue is his faithfulness recited generations later.$n$,$n$Nehemiah 9:24 — *So the children went in and possessed the land, and thou subduedst before them the inhabitants of the land, the Canaanites, and gavest them into their hands, with their kings, and the people of the land, that they might do with them as they would.* *The king of Tirzah, one: all the kings thirty and one.* (Joshua 12:24) The kings of Joshua's list were not beaten by a stronger people. The Levites say it to Yahuah (the LORD) himself in their confession: *thou subduedst before them the inhabitants of the land*, and *gavest them into their hands, with their kings*. Thirty and one is the number of times he did it. The memorial counts; the confession says whom to thank.$n$),
(5516,'canon','revelation',1,7,$n$Behold, he comes with clouds; and every eye shall see him, and they also which pierced him: and all kindreds of the earth shall wail because of him. Even so, Amen.$n$,'canon','matthew',24,27,$n$thread:like-the-son-of-adam-coming-with-the-clouds | *As the lightning cometh out of the east, and shineth even unto the west; so shall also the coming of the Son of Adam be* — the east-direction qualifier of the cloud-rider's coming. Apply son-of-Adam restoration.$n$,$n$Matthew 24:27 — *For as the lightning cometh out of the east, and shineth even unto the west; so shall also the coming of the Son of Adam be.* *Behold, he comes with clouds; and every eye shall see him, and they also which pierced him: and all kindreds of the earth shall wail because of him. Even so, Amen.* (Revelation 1:7) John says every eye shall see him come with the clouds. Matthew tells how a coming can be seen by every eye: like lightning out of the east that shines to the west, the whole sky at once, nothing hidden in a corner. The verse before it warns, *Behold, he is in the desert; go not forth: behold, he is in the secret chambers; believe it not* (Matthew 24:26). A coming every eye sees is a coming no one has to be told about.$n$),
(177482,'canon','revelation',11,12,$n$And they heard a great voice from heaven saying unto them, Come up hither. And they ascended up to heaven in a cloud; and their enemies beheld them.$n$,'canon','john',3,13,$n$*And no man hath ascended up to heaven, but he that came down from heaven, even the Son of Adam which is in heaven.* (John 3:13). Until this voice, no man but the Son of Adam had gone up to heaven. Here, after the reign and the little season, the raised witnesses hear *Come up hither. And they ascended up to heaven in a cloud* (Revelation 11:12) — the first time the scriptures show his people going up to heaven, the catching-up Paul named: *caught up together with them in the clouds* (1 Thessalonians 4:17).$n$,$n$John 3:13 — *And no man hath ascended up to heaven, but he that came down from heaven, even the Son of Adam which is in heaven.* *And they heard a great voice from heaven saying unto them, Come up hither. And they ascended up to heaven in a cloud; and their enemies beheld them.* (Revelation 11:12) Yahusha (Jesus) told Nicodemus that no man had gone up to heaven but the Son of Adam who came down from it. The Revelation shows when that changes: after the reign and the little season the raised witnesses hear *Come up hither* and ascend in a cloud while their enemies look on. This is the going up of his people that Paul set after the rising of the dead, *caught up together with them in the clouds* (1 Thessalonians 4:17).$n$),
(177477,'canon','revelation',11,18,$n$And the nations were angry, and your wrath is come, and the time of the dead, that they should be judged, and that you should give reward unto your servants the prophets, and to the saints, and them that fear your name, small and great; and should destroy them which destroy the earth.$n$,'pseudepigrapha','testaments-xii',140,8,$n$*'And' then shall ye see Enoch, Noah, and Shem, and Abraham, and Isaac, and Jacob, rising on the right hand in gladness. Then shall we also rise, each one over our tribe, worshipping the King of heaven... Then also all men shall rise, some unto glory and some unto shame. And Yahuah (Lord) shall judge Yashar'el (Israel) first, for their unrighteousness... And then shall He judge all the Gentiles...* (Testaments of the Twelve Patriarchs 140:6–9). Benjamin sets the rising in order: the fathers first, then the sons each over his tribe, and last *all men shall rise, some unto glory and some unto shame,* and then the judging. Revelation names that last hour: *the time of the dead, that they should be judged* (Revelation 11:18). The fathers and the tribes rise before; the rising of all men, to glory or to shame, comes at the time of the dead, when the one judgment is set.$n$,$n$Testaments of the Twelve Patriarchs 140:8 — *Then also all men shall rise, some unto glory and some unto shame. And Yahuah (Lord) shall judge Yashar'el (Israel) first, for their unrighteousness; [for when He appeared as Elohim (God) in the flesh to deliver them they believed Him not].* *And the nations were angry, and your wrath is come, and the time of the dead, that they should be judged, and that you should give reward unto your servants the prophets, and to the saints, and them that fear your name, small and great; and should destroy them which destroy the earth.* (Revelation 11:18) The seventh trumpet names *the time of the dead, that they should be judged*. Benjamin's testament sets that hour in an order. First the fathers: *then shall ye see Enoch, Noah, and Shem, and Abraham, and Isaac, and Jacob, rising on the right hand in gladness* (Testaments of the Twelve Patriarchs 140:6). Only after them *all men shall rise, some unto glory and some unto shame*, and the judging begins. That last rising is what the trumpet calls the time of the dead.$n$),
(177478,'canon','revelation',20,4,$n$And I saw thrones, and they sat upon them, and judgment was given unto them: and I saw the souls of them that were beheaded for the witness of Yahusha (Jesus), and for the word of Elohim (God), and which had not worshipped the beast, neither his image, neither had received his mark upon their foreheads, or in their hands; and they lived and reigned with Messiah (Christ) a thousand years.$n$,'pseudepigrapha','testaments-xii',60,1,$n$*And after these things shall Abraham and Isaac and Jacob arise unto life, and I and my brethren shall be chiefs of the tribes 'of Israel': Levi first, I the second, Joseph third, Benjamin fourth, Simeon fifth, Issachar sixth, and so all in order... And ye shall be the people of Yahuah (Lord), and have one tongue; And there shall be there no spirit of deceit of 'Beliar', For he shall be cast into the fire for ever. And they who have died in grief shall arise 'in joy', 'And they who were poor for Yahuah's (Lord's) sake shall be made rich,' And they who are put to death for Yahuah's (Lord's) sake shall awake 'to life'.* (Testaments of the Twelve Patriarchs 60:1, 3–4). John sees *the souls of them that were beheaded for the witness of Yahusha (Jesus)... and they lived and reigned with Messiah (Christ) a thousand years* (Revelation 20:4). Judah's testament holds the same rising: the fathers *arise unto life,* the sons stand as *chiefs of the tribes* *all in order,* and *they who are put to death for Yahuah's (Lord's) sake shall awake 'to life'.* The first resurrection raises the fathers and the faithful slain into an ordered kingdom of the tribes, and the deceiver has no place among them, as John sees him shut in the pit *that he should deceive the nations no more* (Revelation 20:3), until his end in the fire.$n$,$n$Testaments of the Twelve Patriarchs 60:1 — *And after these things shall Abraham and Isaac and Jacob arise unto life, and I and my brethren shall be chiefs of the tribes 'of Israel': Levi first, I the second, Joseph third, Benjamin fourth, Simeon fifth, Issachar sixth, and so all in order.* *And I saw thrones, and they sat upon them, and judgment was given unto them: and I saw the souls of them that were beheaded for the witness of Yahusha (Jesus), and for the word of Elohim (God), and which had not worshipped the beast, neither his image, neither had received his mark upon their foreheads, or in their hands; and they lived and reigned with Messiah (Christ) a thousand years.* (Revelation 20:4) John sees the beheaded live and reign with Messiah (Christ) a thousand years. The testament of Yahudah (Judah) holds the same rising and sets it in order: Abraham, Isaac and Jacob *arise unto life*, and the twelve sons stand as *chiefs of the tribes*, Levi first and so all in order. The first resurrection raises the fathers and the faithful slain into a kingdom laid out by tribes, and they reign with him.$n$),
(177479,'canon','revelation',20,7,$n$And when the thousand years are expired, Satan shall be loosed out of his prison,$n$,'canon','isaiah',24,22,$n$*And it shall come to pass in that day, that Yahuah (LORD) shall punish the host of the high ones that are on high, and the kings of the earth upon the earth. And they shall be gathered together, as prisoners are gathered in the pit, and shall be shut up in the prison, and after many days shall they be visited. Then the moon shall be confounded, and the sun ashamed, when Yahuah Tseva'ot (LORD of hosts) shall reign in mount Zion, and in Jerusalem, and before his ancients gloriously.* (Isaiah 24:21-23). Isaiah saw the host on high *gathered in the pit* and *shut up in the prison,* while *Yahuah Tseva'ot (LORD of hosts) shall reign in mount Zion*. The shutting up is not the end of them: *after many days shall they be visited.* John sees the prison opened when the many days of the reign are done: *when the thousand years are expired, Satan shall be loosed out of his prison* (Revelation 20:7) — the little season, before the last judgment.$n$,$n$Isaiah 24:22 — *And they shall be gathered together, as prisoners are gathered in the pit, and shall be shut up in the prison, and after many days shall they be visited.* *And when the thousand years are expired, Satan shall be loosed out of his prison,* (Revelation 20:7) Isaiah saw the host of the high ones gathered like prisoners into the pit and shut up in the prison, and he added the clause that keeps the prison from being their end: *after many days shall they be visited*. John gives the many days their measure. When the thousand years are expired Satan is loosed out of his prison for a little season, and his end comes after it, not in the chain.$n$),
(177476,'canon','revelation',20,12,$n$And I saw the dead, small and great, stand before Elohim (God); and the books were opened: and another book was opened, which is the book of life: and the dead were judged out of those things which were written in the books, according to their works.$n$,'pseudepigrapha','testaments-xii',140,8,$n$*'And' then shall ye see Enoch, Noah, and Shem, and Abraham, and Isaac, and Jacob, rising on the right hand in gladness. Then shall we also rise, each one over our tribe, worshipping the King of heaven... Then also all men shall rise, some unto glory and some unto shame. And Yahuah (Lord) shall judge Yashar'el (Israel) first, for their unrighteousness... And then shall He judge all the Gentiles...* (Testaments of the Twelve Patriarchs 140:6–9). John sees *the dead, small and great, stand before Elohim (God)... and the dead were judged out of those things which were written in the books, according to their works* (Revelation 20:12). Benjamin's *all men shall rise, some unto glory and some unto shame* is that standing of small and great: the rising first, then the judging.$n$,$n$Testaments of the Twelve Patriarchs 140:8 — *Then also all men shall rise, some unto glory and some unto shame. And Yahuah (Lord) shall judge Yashar'el (Israel) first, for their unrighteousness; [for when He appeared as Elohim (God) in the flesh to deliver them they believed Him not].* *And I saw the dead, small and great, stand before Elohim (God); and the books were opened: and another book was opened, which is the book of life: and the dead were judged out of those things which were written in the books, according to their works.* (Revelation 20:12) John sees small and great standing before the opened books. Benjamin's testament names the same standing: *all men shall rise, some unto glory and some unto shame*, and after the rising the judging. The order is the same in both, the dead raised first and then judged out of what is written, and the two ends of it, glory and shame, are the two the opened books divide.$n$),
(177448,'canon','romans',11,15,$n$For if the casting away of them be the reconciling of the world, what shall the receiving of them be, but life from the dead?$n$,'canon','jeremiah',16,15,$n$*But, Yahuah (LORD) liveth, that brought up the children of Yashar'el (Israel) from the land of the north, and from all the lands whither he had driven them: and I will bring them again into their land that I gave unto their fathers* (Jeremiah 16:15). Paul's *what shall the receiving of them be, but life from the dead?* (Romans 11:15) is this same regathering: the cast-away house, driven into the lands of the north, brought again home. The receiving of them IS the return Jeremiah promised.$n$,$n$Jeremiah 16:15 — *But, Yahuah (LORD) liveth, that brought up the children of Yashar'el (Israel) from the land of the north, and from all the lands whither he had driven them: and I will bring them again into their land that I gave unto their fathers.* *For if the casting away of them be the reconciling of the world, what shall the receiving of them be, but life from the dead?* (Romans 11:15) Paul asks what the receiving of the cast away house will be, and answers, life from the dead. Jeremiah had already described the receiving. The oath that once named the deliverance out of Egypt will be sworn instead by the one who brought the children of Yashar'el (Israel) *from the land of the north* and from every land he drove them to, back into the land given to their fathers. The receiving is a homecoming, and the house that was driven out is the house that comes back.$n$),
(177449,'canon','romans',11,15,$n$For if the casting away of them be the reconciling of the world, what shall the receiving of them be, but life from the dead?$n$,'canon','jeremiah',16,16,$n$*Behold, I will send for many fishers, saith Yahuah (LORD), and they shall fish them* (Jeremiah 16:16). The *receiving of them* that is *life from the dead* (Romans 11:15) is worked by the fishers Yahuah promised to send — the same fishers Yahusha (Jesus) named when he said *I will make you fishers of men* (Matthew 4:19). Paul, apostle to the cast-away Gentiles who are his own flesh, is sent in that fishing: gathering the scattered house home.$n$,$n$Jeremiah 16:16 — *Behold, I will send for many fishers, saith Yahuah (LORD), and they shall fish them; and after will I send for many hunters, and they shall hunt them from every mountain, and from every hill, and out of the holes of the rocks.* *For if the casting away of them be the reconciling of the world, what shall the receiving of them be, but life from the dead?* (Romans 11:15) The receiving Paul calls life from the dead has workmen. Jeremiah hears Yahuah (the LORD) promise fishers first, and after them hunters who search every mountain and hill and the holes of the rocks, so that none of the driven out is left unfound. Yahusha (Jesus) called his first disciples with the same word: *Follow me, and I will make you fishers of men* (Matthew 4:19). Paul, sent among the Gentiles who were his own scattered kin, is in that fishing.$n$),
(177456,'canon','romans',11,25,$n$For I would not, brethren, that you should be ignorant of this mystery, lest you should be wise in your own conceits; that blindness in part is happened to Yashar'el (Israel), until the fulness of the Gentiles be come in.$n$,'canon','luke',21,24,$n$*...and Jerusalem shall be trodden down of the Gentiles, until the times of the Gentiles be fulfilled* (Luke 21:24). The twin of *until the fulness of the Gentiles be come in* (Romans 11:25). The same fullness ends both: the desolation runs its course and the scattered seed comes home at the one hour.$n$,$n$Luke 21:24 — *And they shall fall by the edge of the sword, and shall be led away captive into all nations: and Jerusalem shall be trodden down of the Gentiles, until the times of the Gentiles be fulfilled.* *For I would not, brethren, that you should be ignorant of this mystery, lest you should be wise in your own conceits; that blindness in part is happened to Yashar'el (Israel), until the fulness of the Gentiles be come in.* (Romans 11:25) Two sentences, two untils. Yahusha (Jesus) says Jerusalem is trodden down of the Gentiles *until the times of the Gentiles be fulfilled*; Paul says the blindness on Yashar'el (Israel) is in part and lasts *until the fulness of the Gentiles be come in*. Neither verse spells out who these Gentiles are. What both say is that the treading down and the blindness have a term set to them, and Paul's next words name what follows: *And so all Yashar'el (Israel) shall be saved* (Romans 11:26).$n$),
(177480,'canon','1-thessalonians',4,17,$n$Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord.$n$,'ascension-isaiah','ascension-isaiah',9,9,$n$*And there I saw Enoch and all who were with him, stript of the garments of the flesh, and I saw them in their garments of the upper world, and they were like angels, standing there in great glory.* (Ascension of Isaiah 9:9). Those on high are seen *stript of the garments of the flesh* and clothed *in their garments of the upper world* — the garments of 4:17, where the saints *turn themselves upward in their garments, and their body will be left in the world.* So the catching-up Paul names — *caught up together with them in the clouds, to meet Yahusha (Lord) in the air: and so shall we ever be with Yahusha (Lord)* (1 Thessalonians 4:17) — is a going up out of the garments of the flesh into the garments of the upper world, after the reign.$n$,$n$Ascension of Isaiah 9:9 — *And there I saw Enoch and all who were with him, stript of the garments of the flesh, and I saw them in their garments of the upper world, and they were like angels, standing there in great glory.* *Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord.* (1 Thessalonians 4:17) Isaiah, carried up through the heavens, sees Enoch and all who were with him *stript of the garments of the flesh* and standing in *their garments of the upper world*, like angels in great glory. Paul's catching up is a going up of that kind: the living and the raised taken together *to meet the Lord in the air*, the flesh left behind and the glory put on. It comes after the reign; *the dead in Messiah (Christ) shall rise first* (1 Thessalonians 4:16) is an earlier hour.$n$),
(177481,'canon','1-thessalonians',4,17,$n$Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord.$n$,'ascension-isaiah','ascension-isaiah',4,17,$n$*And afterwards they will turn themselves upward in their garments, and their body will be left in the world.* (Ascension of Isaiah 4:17). Isaiah's *afterwards* keeps the order Paul keeps: *Then we which are alive and remain shall be caught up together with them in the clouds, to meet Yahusha (Lord) in the air* (1 Thessalonians 4:17). The going up comes after the reign and the little season, when the voice says *Come up hither* and *they ascended up to heaven in a cloud* (Revelation 11:12). They turn upward in their garments, and the body is left in the world — as it is written, *it is appointed unto men once to die, but after this the judgment* (Hebrews 9:27).$n$,$n$Ascension of Isaiah 4:17 — *And afterwards they will turn themselves upward in their garments, and their body will be left in the world.* *Then we which are alive and remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord.* (1 Thessalonians 4:17) Isaiah's *afterwards* is Paul's *Then*. The going up does not open the story; it closes it. After the reign and the little season the saints *turn themselves upward in their garments*, and *their body will be left in the world*: the flesh stays, the garment goes up. Paul says the same of the living who remain, *caught up together with them in the clouds*, and sets it after the dead have risen, not before.$n$),
(177447,'canon','genesis',35,11,$n$And Elohim (God) said unto him, I am El Shaddai (God Almighty): be fruitful and multiply; a nation and a company of nations shall be of you, and kings shall come out of your loins;$n$,'canon','romans',11,25,$n$*...that blindness in part is happened to Yashar'el (Israel), until the fulness of the Gentiles be come in* (Romans 11:25). The *company of nations* sworn to Jacob at Bethel — *a nation and a company of nations shall be of thee* (Genesis 35:11), qehal goyim — runs through Ephraim, whose seed becomes a multitude of nations (Genesis 48:19, melo ha-goyim), and arrives as the *fulness of the Gentiles*. Not nations grafted in from outside, but the covenant seed scattered among the nations and gathered home.$n$,$n$Romans 11:25 — *For I would not, brethren, that ye should be ignorant of this mystery, lest ye should be wise in your own conceits; that blindness in part is happened to Yashar'el (Israel), until the fulness of the Gentiles be come in.* *And Elohim (God) said unto him, I am El Shaddai (God Almighty): be fruitful and multiply; a nation and a company of nations shall be of you, and kings shall come out of your loins;* (Genesis 35:11) El Shaddai (God Almighty) promises Jacob at Bethel *a nation and a company of nations*. Jacob later says of Ephraim, *his seed shall become a multitude of nations* (Genesis 48:19), and the house of Joseph became that, scattered and grown up among the nations. Paul's *fulness of the Gentiles* is that company come in at last. Not nations added to the house from outside, but Jacob's own company of nations gathered home, and the blindness in part ending when they are.$n$),
(135800,'canon','ezekiel',17,22,$n$Thus says Adonai Yahuah (the Lord GOD); I will also take of the highest branch of the high cedar, and will set it; I will crop off from the top of his young twigs a tender one, and will plant it upon an high mountain and eminent:$n$,'canon','jeremiah',23,5,$n$*Behold, the days come, saith Yahuah (LORD), that I will raise unto David a righteous Branch, and a King shall reign and prosper, and shall execute judgment and justice in the earth* (Jeremiah 23:5). The cedar-twig Yahuah plants to *be a goodly cedar* (Ezekiel 17:23) is the *righteous Branch* raised unto David — a King who reigns where the faithless king fell. The planted twig becomes the reigning, righteous King.$n$,$n$Jeremiah 23:5 — *Behold, the days come, saith Yahuah (LORD), that I will raise unto David a righteous Branch, and a King shall reign and prosper, and shall execute judgment and justice in the earth.* *Thus says Adonai Yahuah (the Lord GOD); I will also take of the highest branch of the high cedar, and will set it; I will crop off from the top of his young twigs a tender one, and will plant it upon an high mountain and eminent:* (Ezekiel 17:22) Ezekiel's twig is cropped from the top of the high cedar, tender, and planted by Yahuah's (the LORD's) own hand on the mountain. Jeremiah names what grows from it: a *righteous Branch* raised unto David, *a King* who reigns and does judgment in the earth. Where Zedekiah's vine withered for a broken oath, the planted twig becomes the reigning king, and Jeremiah's next verse gives the fruit: *In his days Yahudah (Judah) shall be saved, and Yashar'el (Israel) shall dwell safely* (Jeremiah 23:6), both houses under the one Branch.$n$),
(177475,'apocrypha','2-esdras',7,30,$n$And the world shall be turned into the old silence seven days, like as in the former judgments: so that no man shall remain.$n$,'canon','jeremiah',4,23,$n$*And the world shall be turned into the old silence seven days, like as in the former judgments: so that no man shall remain.* (2 Esdras 7:30). *I beheld the earth, and, lo, it was without form, and void; and the heavens, and they had no light.* (Jeremiah 4:23). Esdras is told the world returns to the old silence for seven days, no man remaining. Jeremiah was shown the like: the earth *without form, and void,* the heavens without light, and, as he goes on, *lo, there was no man* (Jeremiah 4:25). These are the words of the earth before the first day, when *the earth was without form, and void; and darkness was upon the face of the deep* (Genesis 1:2); the old silence is the earth returned to that first stillness, no man remaining, before *the earth shall restore those that are asleep in her* (2 Esdras 7:32).$n$,$n$Jeremiah 4:23 — *I beheld the earth, and, lo, it was without form, and void; and the heavens, and they had no light.* *And the world shall be turned into the old silence seven days, like as in the former judgments: so that no man shall remain.* (2 Esdras 7:30) Esdras is told the world goes back to *the old silence* for seven days, *so that no man shall remain*. Jeremiah was shown that silence from inside it: the earth *without form, and void*, the heavens dark, and two verses on, *I beheld, and, lo, there was no man* (Jeremiah 4:25). They are the words of the first day before the light, *the earth was without form, and void* (Genesis 1:2). The old silence is the earth back in its first stillness, before it gives up its sleepers.$n$),
(133755,'pseudepigrapha','2-baruch',50,3,$n$For then it will be necessary to show to the living that the dead have come to life again, and that those who had departed have returned (again).$n$,'canon','john',20,25,$n$John 20:25 — *Except I shall see in his hands the print of the nails... and thrust my hand into his side, I will not believe.* Thomas is not doubting the resurrection; he is applying it — a true rising returns the same form, known by its marks.$n$,$n$John 20:25 — *The other disciples therefore said unto him, We have seen Yahusha (Lord). But he said unto them, Except I shall see in his hands the print of the nails, and put my finger into the print of the nails, and thrust my hand into his side, I will not believe.* *For then it will be necessary to show to the living that the dead have come to life again, and that those who had departed have returned (again).* (2 Baruch 50:3) Baruch is told the dead come back in the form they went down in, so the living may know them for the same people. Thomas asks for exactly that: he will believe the risen one is the crucified one when he sees *the print of the nails* and puts his hand into the side. The marks are how the same man is known. He is not doubting a resurrection; he is holding it to its rule, and Yahusha (Jesus) met him there: *behold my hands* (John 20:27).$n$);
CREATE TEMP TABLE _s503_m (thread_slug TEXT, thread_id BIGINT, card_id BIGINT, ord INT, member_note TEXT) ON COMMIT DROP;
INSERT INTO _s503_m VALUES
('joshua-12-sihon-and-og-the-two-great-kings-overthrown',39760,161403,12002,$n$Psalm 136:19 — *Sihon king of the Amorites: for his mercy endureth for ever:* Sihon's fall sung by name as a deed of Yahuah's (the LORD's) mercy that endureth for ever.$n$),
('joshua-12-sihon-and-og-the-two-great-kings-overthrown',39760,161404,12002,$n$Psalm 135:11 — *Sihon king of the Amorites, and Og king of Bashan, and all the kingdoms of Canaan:* Sihon and Og named together with all the kingdoms of Canaan, the heads of Joshua's roll in one line of praise.$n$),
('joshua-12-sihon-and-og-the-two-great-kings-overthrown',39760,161407,12004,$n$Psalm 136:20 — *And Og the king of Bashan: for his mercy endureth for ever:* Og the giant king named in the psalm as a deed of Yahuah's (the LORD's) enduring mercy.$n$),
('joshua-12-the-land-given-for-an-heritage-as-yahuah-promised-the-fathers',39761,161408,12006,$n$Deuteronomy 3:18 — *hath given you this land to possess it: ye shall pass over armed before your brethren.* Moses' command at the giving of the east country: the land is Yahuah's (the LORD's) gift, and the tribes who hold it fight for their brethren.$n$),
('joshua-12-the-land-given-for-an-heritage-as-yahuah-promised-the-fathers',39761,161409,12006,$n$Psalm 136:21 — *And gave their land for an heritage: for his mercy endureth for ever:* The land given for an heritage by Yahuah's (the LORD's) mercy, not held as a possession won by the sword.$n$),
('joshua-12-the-land-given-for-an-heritage-as-yahuah-promised-the-fathers',39761,161410,12006,$n$Psalm 136:22 — *Even an heritage unto Yashar'el (Israel) his servant: for his mercy endureth for ever.* The heritage is Yashar'el's (Israel's), his servant, the whole house, given by mercy that endureth for ever.$n$),
('joshua-12-the-land-given-for-an-heritage-as-yahuah-promised-the-fathers',39761,161411,12007,$n$Nehemiah 9:23 — *broughtest them into the land, concerning which thou hadst promised to their fathers.* The children multiplied as the stars and brought into the land promised to their fathers: the dividing of Joshua 12 is the promise kept.$n$),
('joshua-12-the-land-given-for-an-heritage-as-yahuah-promised-the-fathers',39761,161412,12007,$n$Nehemiah 9:24 — *thou subduedst before them the inhabitants of the land, the Canaanites, and gavest them into their hands, with their kings.* The Levites' confession gives the subduing of the kings and the giving of the land to Yahuah (the LORD), not to Joshua.$n$),
('joshua-12-the-land-given-for-an-heritage-as-yahuah-promised-the-fathers',39761,161413,12007,$n$Psalm 135:12 — *And gave their land for an heritage, an heritage unto Yashar'el (Israel) his people.* The land given as an heritage unto Yashar'el (Israel) his people, and the psalm turns at once to the name of the giver.$n$),
('joshua-12-the-memorial-of-the-kings-yahuah-smote',39759,161398,12024,$n$Psalm 136:17 — *To him which smote great kings: for his mercy endureth for ever:* The great kings smitten, the closing tally of Joshua's roll sung as one line of Yahuah's (the LORD's) mercy.$n$),
('joshua-12-the-memorial-of-the-kings-yahuah-smote',39759,161399,12024,$n$Psalm 135:10 — *Who smote great nations, and slew mighty kings;* Great nations smitten and mighty kings slain: the psalm's uncounted line for Joshua's thirty and one.$n$),
('joshua-12-the-memorial-of-the-kings-yahuah-smote',39759,161400,12024,$n$Nehemiah 9:24 — *thou subduedst before them the inhabitants of the land, the Canaanites, and gavest them into their hands, with their kings.* The Levites confess that Yahuah (the LORD) subdued the land and gave its kings into Yashar'el's (Israel's) hands: Joshua's thirty and one.$n$),
('revelation-1-behold-he-cometh-with-clouds-and-they-which-pierced-him-zechariah-12',1916,5516,1007,$n$Matthew 24:27 — *For as the lightning cometh out of the east, and shineth even unto the west; so shall also the coming of the Son of Adam be.* The coming seen as lightning from east to west, the whole sky at once, so that every eye sees it.$n$),
('revelation-11-the-spirit-of-life-entered-them-and-they-ascended-in-a-cloud-ezekiel-37',2080,177482,11012,$n$John 3:13 — *And no man hath ascended up to heaven, but he that came down from heaven, even the Son of Adam which is in heaven.* No man had ascended to heaven but the Son of Adam who came down, until the witnesses are called up.$n$),
('revelation-11-the-kingdoms-become-the-kingdoms-of-our-lord-and-of-his-messiah-daniel-2-7',2081,177477,11018,$n$Testaments of the Twelve Patriarchs 140:8 — *Then also all men shall rise, some unto glory and some unto shame.* All men rise, some to glory and some to shame, and then the judging: the time of the dead the trumpet names.$n$),
('revelation-20-the-thrones-of-judgment-and-the-first-resurrection-daniel-7-ezekiel-37',2418,177478,20004,$n$Testaments of the Twelve Patriarchs 60:1 — *shall Abraham and Isaac and Jacob arise unto life.* The fathers arise unto life and the sons stand as chiefs of the tribes: the first resurrection set out in order.$n$),
('revelation-20-the-dragon-bound-a-thousand-years-the-old-serpent-shut-in-the-pit-isaiah-24',2417,177479,20007,$n$Isaiah 24:22 — *and after many days shall they be visited.* The host shut up in the prison and visited after many days: the prison has a term set to it.$n$),
('revelation-20-the-books-were-opened-and-the-book-of-life-daniel-7-and-12',2423,177476,20012,$n$Testaments of the Twelve Patriarchs 140:8 — *Then also all men shall rise, some unto glory and some unto shame.* All men rise to glory or to shame and then are judged: the standing of small and great before the opened books.$n$),
('romans-11-through-their-fall-the-receiving-of-them-life-from-the-dead',1615,177448,11015,$n$Jeremiah 16:15 — *from the land of the north, and from all the lands whither he had driven them.* The children brought back from the north and from every land they were driven to, into the land of their fathers.$n$),
('romans-11-through-their-fall-the-receiving-of-them-life-from-the-dead',1615,177449,11015,$n$Jeremiah 16:16 — *I will send for many fishers, saith Yahuah (LORD), and they shall fish them.* Fishers sent first and hunters after them, until the driven out are found in every hill and every hole of the rocks.$n$),
('romans-11-blindness-in-part-until-the-fulness-and-so-all-israel-shall-be-saved',1617,177456,11025,$n$Luke 21:24 — *Jerusalem shall be trodden down of the Gentiles, until the times of the Gentiles be fulfilled.* Jerusalem trodden down of the Gentiles until their times are fulfilled: the same term as the blindness in part.$n$),
('1-thessalonians-4-the-dead-in-messiah-rise-the-trump-of-gathering-isaiah-27-daniel-12',13703,177480,4017,$n$Ascension of Isaiah 9:9 — *stript of the garments of the flesh.* Enoch and those with him seen stript of the flesh and clothed in the garments of the upper world, like angels.$n$),
('1-thessalonians-4-the-dead-in-messiah-rise-the-trump-of-gathering-isaiah-27-daniel-12',13703,177481,4017,$n$Ascension of Isaiah 4:17 — *And afterwards they will turn themselves upward in their garments, and their body will be left in the world.* Afterwards they turn upward in their garments and the body is left in the world: the going up comes last.$n$),
('genesis-35-i-am-el-shaddai-a-company-of-nations',12782,177447,35011,$n$Romans 11:25 — *until the fulness of the Gentiles be come in.* The blindness in part lasts until the fulness of the Gentiles, Jacob's company of nations, is come in.$n$),
('ezekiel-17-the-tender-twig-planted-into-a-goodly-cedar',33965,135800,17022,$n$Jeremiah 23:5 — *I will raise unto David a righteous Branch, and a King shall reign and prosper.* The righteous Branch raised unto David, a King who reigns: what Ezekiel's planted twig grows into.$n$),
('2-esdras-7-silence-and-the-raising',10791,177475,7030,$n$Jeremiah 4:23 — *I beheld the earth, and, lo, it was without form, and void; and the heavens, and they had no light.* The earth without form and void and the heavens without light: the old silence as Jeremiah saw it.$n$),
('resurrection-keeps-the-form',33546,133755,50003,$n$John 20:25 — *Except I shall see in his hands the print of the nails.* Thomas asks to see the print of the nails: the risen one known as the crucified one by the marks he kept.$n$);

CREATE OR REPLACE TEMP VIEW _s503_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id, v.text
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id JOIN editions e ON b.edition_id = e.id;

DO $s503$
DECLARE r RECORD; sid BIGINT; tid BIGINT; ltext TEXT; cur RECORD; n INT; n_note INT := 0; n_note_same INT := 0; n_mem INT := 0; n_mem_same INT := 0; n_total INT;
BEGIN
  FOR r IN SELECT * FROM _s503_c LOOP
    SELECT verse_id, text INTO sid, ltext FROM _s503_lookup WHERE edition_slug = r.s_ed AND book_slug = r.s_book AND chapter_number = r.src_ch AND verse_number = r.src_v;
    IF sid IS NULL THEN RAISE EXCEPTION 'S503: source verse %/% %:% missing', r.s_ed, r.s_book, r.src_ch, r.src_v; END IF;
    IF ltext <> r.src_text THEN RAISE EXCEPTION 'S503: live text of %/% %:% differs from the read-back this migration was written against — re-dump and rebuild', r.s_ed, r.s_book, r.src_ch, r.src_v; END IF;
    SELECT verse_id INTO tid FROM _s503_lookup WHERE edition_slug = r.t_ed AND book_slug = r.tgt_slug AND chapter_number = r.tgt_ch AND verse_number = r.tgt_v;
    IF tid IS NULL THEN RAISE EXCEPTION 'S503: target verse %/% %:% missing', r.t_ed, r.tgt_slug, r.tgt_ch, r.tgt_v; END IF;
    SELECT * INTO cur FROM cross_references WHERE id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503: card % is gone', r.id; END IF;
    IF cur.source_verse_id <> sid OR cur.target_verse_id <> tid THEN RAISE EXCEPTION 'S503: card % no longer sits on %/% %:% -> %/% %:%', r.id, r.s_ed, r.s_book, r.src_ch, r.src_v, r.t_ed, r.tgt_slug, r.tgt_ch, r.tgt_v; END IF;
    IF cur.note IS DISTINCT FROM r.old_note AND cur.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503: the live note of card % differs from the read-back this migration was written against — re-dump and rebuild', r.id; END IF;
    IF EXISTS (SELECT 1 FROM cross_reference_thread_members mm JOIN cross_reference_threads th ON th.id = mm.thread_id
                WHERE mm.cross_reference_id = r.id AND NOT EXISTS (SELECT 1 FROM _s503_m m WHERE m.card_id = r.id AND m.thread_slug = th.slug)) THEN
      RAISE EXCEPTION 'S503: card % already sits in a thread this migration does not put it in — re-dump and rebuild', r.id; END IF;
  END LOOP;
  FOR r IN SELECT DISTINCT thread_slug, thread_id FROM _s503_m LOOP
    IF NOT EXISTS (SELECT 1 FROM cross_reference_threads WHERE slug = r.thread_slug AND id = r.thread_id) THEN
      RAISE EXCEPTION 'S503: thread to join % (id %) does not exist under that id — re-dump and rebuild', r.thread_slug, r.thread_id; END IF;
  END LOOP;

  SELECT count(*) INTO n_total FROM _s503_c;
  UPDATE cross_references x SET note = c.new_note FROM _s503_c c WHERE x.id = c.id AND x.note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_note = ROW_COUNT; n_note_same := n_total - n_note;

  SELECT count(*) INTO n_total FROM _s503_m;
  INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
  SELECT th.id, m.card_id,
         COALESCE((SELECT max(mm.sort_order) FROM cross_reference_thread_members mm WHERE mm.thread_id = th.id), 0)
           + row_number() OVER (PARTITION BY th.id ORDER BY m.ord, m.card_id),
         m.member_note
    FROM _s503_m m JOIN cross_reference_threads th ON th.slug = m.thread_slug
   WHERE NOT EXISTS (SELECT 1 FROM cross_reference_thread_members mm WHERE mm.thread_id = th.id AND mm.cross_reference_id = m.card_id)
  ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
  GET DIAGNOSTICS n_mem = ROW_COUNT; n_mem_same := n_total - n_mem;

  SELECT count(*) INTO n FROM _s503_c c JOIN cross_references x ON x.id = c.id WHERE x.note IS DISTINCT FROM c.new_note;
  IF n > 0 THEN RAISE EXCEPTION 'S503: % card(s) do not carry the new note', n; END IF;
  SELECT count(*) INTO n FROM _s503_m m WHERE NOT EXISTS (
    SELECT 1 FROM cross_reference_thread_members mm JOIN cross_reference_threads th ON th.id = mm.thread_id AND th.slug = m.thread_slug WHERE mm.cross_reference_id = m.card_id);
  IF n > 0 THEN RAISE EXCEPTION 'S503: % member row(s) did not land', n; END IF;

  RAISE NOTICE 'S503 (stragglers) summary: notes rewritten % / already there %; members inserted % / already there %', n_note, n_note_same, n_mem, n_mem_same;
END $s503$;
COMMIT;
\echo 'session503 — stragglers rebuild done.'
